<script>
document.addEventListener('DOMContentLoaded',()=>{const menu=document.querySelector('[data-ca50-menu]'),nav=document.querySelector('[data-ca50-nav]');menu?.addEventListener('click',()=>nav?.classList.toggle('is-open'));const hero=document.querySelector('[data-ca50-slider]');if(hero){const slides=[...hero.querySelectorAll('.ca50-hero-slide')];let active=0;const show=n=>{active=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('is-active',i===active))};hero.querySelector('[data-ca50-prev]')?.addEventListener('click',()=>show(active-1));hero.querySelector('[data-ca50-next]')?.addEventListener('click',()=>show(active+1));if(slides.length>1)setInterval(()=>show(active+1),5600)}document.querySelectorAll('.ca50-accordion article button').forEach(button=>button.addEventListener('click',()=>button.parentElement.classList.toggle('is-open')))});
</script>
